// SMETA (Sedex Members Ethical Trade Audit) checker — SMETA 7 audit report and
// Corrective Action Plan Report (CAPR) as generated by the Sedex platform.
import { cells, collector, clip, ymd, textDates, fmt, days, num, NEG, PLACEHOLDER, norm } from './common.js'

export const RULES = {
  'SMETA-01': { sev: 'error', en: 'Key audit or site field missing (references, site, audit company, dates, audit type, pillars, lead auditor, APSCA number, declarations)', zh: '关键审核或工厂字段缺失（编号、工厂、审核机构、日期、审核类型、支柱、主审核员、APSCA 编号、声明）' },
  'SMETA-02': { sev: 'error', en: 'Audit dates out of order or implausible (audit date vs start/end, declaration dates, time in/out, audit days)', zh: '审核日期顺序错误或不合理（审核日期与开始/结束日期、声明日期、进出时间、审核天数）' },
  'SMETA-03': { sev: 'warning', en: 'Reference number format wrong (ZAA / ZS / ZC / ZAF) or page footers disagree with the audit details', zh: '编号格式错误（ZAA / ZS / ZC / ZAF）或页脚与审核信息不一致' },
  'SMETA-04': { sev: 'info', en: 'Finding reference blank ("ZAF-"): the PDF was generated before the findings were submitted on Sedex', zh: '发现编号为空（“ZAF-”）：PDF 在发现提交到 Sedex 之前生成' },
  'SMETA-05': { sev: 'error', en: 'Summary of findings does not match the finding details (missing finding, type, code area, workplace requirement, local-law flag)', zh: '发现汇总与发现明细不一致（缺少发现、类型、条款、工作场所要求、当地法律标记）' },
  'SMETA-06': { sev: 'error', en: 'Code-section summary disagrees with the overall summary of findings', zh: '各条款章节的汇总与总体发现汇总不一致' },
  'SMETA-07': { sev: 'error', en: 'Non-compliance incomplete: issue title, description, corrective action, status, time given or verification method missing', zh: '不符合项不完整：缺少问题标题、描述、纠正措施、状态、整改期限或验证方式' },
  'SMETA-08': { sev: 'error', en: 'Local-law non-compliance without a local law reference, or local law issue not linked to a finding', zh: '当地法律不符合项缺少法律依据，或当地法律问题未对应任何发现' },
  'SMETA-09': { sev: 'warning', en: 'Corrective action only repeats the description or issue title', zh: '纠正措施只是重复描述或问题标题' },
  'SMETA-10': { sev: 'warning', en: 'Issue title contradicts the description (e.g. title "has been completed", description "not completed")', zh: '问题标题与描述矛盾（如标题称“已完成”，描述称“未完成”）' },
  'SMETA-11': { sev: 'warning', en: 'CAPR timeline: due date ≠ audit end + time given, closed before the audit ended or after the PDF date, or open past due', zh: 'CAPR 时间线：截止日期 ≠ 审核结束 + 整改期限，审核结束前或 PDF 日期之后关闭，或已逾期仍未关闭' },
  'SMETA-12': { sev: 'error', en: 'Worker numbers do not add up (men + women = total, worker types, migrants, pay types, percentages)', zh: '工人人数加总不一致（男 + 女 = 总数、用工类型、外来工、薪酬类型、百分比）' },
  'SMETA-13': { sev: 'error', en: 'Worker interview numbers do not add up or exceed the workforce (groups + individual, by type, "N groups of M")', zh: '工人访谈人数加总不一致或超过工人总数（小组 + 个人、按类型、“N 组每组 M 人”）' },
  'SMETA-14': { sev: 'error', en: 'Wages, hours or age data show a breach (over 60 h/week, 7+ days without a day off, pay below legal minimum, under-age workers) but no NC in that code section', zh: '工资、工时或年龄数据显示违规（每周超 60 小时、连续 7 天以上无休、低于法定最低工资、未达法定年龄）但该条款无不符合项' },
  'SMETA-15': { sev: 'warning', en: 'Working-hours data contradict each other (maximum week above regular hours but zero overtime, average vs regular vs maximum)', zh: '工时数据相互矛盾（最长周工时超过正常工时却记录零加班，平均/正常/最长工时不符）' },
  'SMETA-16': { sev: 'warning', en: 'Data point answer contradicts its own comment or the same question answered elsewhere', zh: '数据点答案与其备注矛盾，或同一问题在别处答案不同' },
  'SMETA-17': { sev: 'warning', en: 'Code section has "No findings" but the evidence text describes a gap', zh: '条款章节为“无发现”，但证据描述中提到缺陷' },
  'SMETA-18': { sev: 'warning', en: 'Environmental data inconsistent (renewable = non-renewable electricity, waste routes exceed total waste, hazardous > total)', zh: '环境数据不一致（可再生与不可再生电量相同、各去向废弃物之和超过总量、危废大于总量）' },
  'SMETA-19': { sev: 'warning', en: 'Audit attendance: absence without a reason, or attendance contradicts the union / worker representative data', zh: '审核出席：缺席未说明理由，或出席情况与工会/工人代表数据矛盾' },
  'SMETA-20': { sev: 'warning', en: 'CAPR signed by someone other than the site representative in the declaration', zh: 'CAPR 签署人与声明中的工厂代表不一致' },
  'SMETA-21': { sev: 'warning', en: 'Spelling error from the common-typo list or a doubled word', zh: '常见拼写错误或重复词' },
  'SMETA-22': { sev: 'warning', en: 'Placeholder or blank text (empty evidence for a code section, "TBC", "provide details" not given)', zh: '占位符或空白文字（条款章节证据为空、“TBC”、选择“提供细节”却未填写）' },
  'SMETA-23': { sev: 'warning', en: 'Sentence pasted twice in a row', zh: '同一句话连续重复粘贴' },
  'SMETA-24': { sev: 'info', en: 'All management-system grades "Robust" in a code section that has non-compliances', zh: '有不符合项的条款章节管理体系评级全部为“健全”' },
  'SMETA-25': { sev: 'error', en: 'Audit report and CAPR for the same audit reference disagree (site, dates, audit company, findings)', zh: '同一审核编号的审核报告与 CAPR 不一致（工厂、日期、审核机构、发现）' },
  'SMETA-26': { sev: 'warning', en: 'Audit pillars do not match the code sections covered (4-pillar without 10.B / 10.C, or 2-pillar with them)', zh: '审核支柱与覆盖的条款章节不符（四支柱缺少 10.B / 10.C，或两支柱却包含）' },
  'SMETA-27': { sev: 'error', en: 'Sample arithmetic: "X out of Y" with X > Y, or a percentage that does not match X/Y', zh: '抽样计算：“X out of Y”中 X > Y，或百分比与 X/Y 不符' },
  'SMETA-28': { sev: 'info', en: 'Layout not recognised as a SMETA 7 platform report: only text-wide checks were run', zh: '版式未识别为 SMETA 7 平台报告：仅运行了全文检查' },
}

const FOOT_Y = 780
const SEC_RE = /^(\d{1,2}(?:\.[A-C])?)\.\s+(.+)$/
const WR_RE = /^(\d{1,2}(?:\.[A-Z]){1,2})\s/
const TIME_RE = /^\d{1,2}:\d{2}$/
const ISO2 = { GH: 'Ghana', VN: 'Vietnam', LV: 'Latvia', CN: 'China', HK: 'Hong Kong', TW: 'Taiwan', IN: 'India', BD: 'Bangladesh', PK: 'Pakistan', LK: 'Sri Lanka', KH: 'Cambodia', MM: 'Myanmar', TH: 'Thailand', MY: 'Malaysia', ID: 'Indonesia', PH: 'Philippines', TR: 'Türkiye', EG: 'Egypt', MA: 'Morocco', TN: 'Tunisia', ZA: 'South Africa', KE: 'Kenya', ET: 'Ethiopia', CI: "Côte d'Ivoire", NG: 'Nigeria', MX: 'Mexico', GT: 'Guatemala', HN: 'Honduras', SV: 'El Salvador', NI: 'Nicaragua', CO: 'Colombia', PE: 'Peru', CL: 'Chile', EC: 'Ecuador', BR: 'Brazil', AR: 'Argentina', US: 'United States', CA: 'Canada', GB: 'United Kingdom', IE: 'Ireland', ES: 'Spain', PT: 'Portugal', IT: 'Italy', FR: 'France', DE: 'Germany', NL: 'Netherlands', BE: 'Belgium', PL: 'Poland', CZ: 'Czechia', SK: 'Slovakia', HU: 'Hungary', RO: 'Romania', BG: 'Bulgaria', LT: 'Lithuania', EE: 'Estonia', UA: 'Ukraine', RS: 'Serbia', GR: 'Greece', IL: 'Israel', JO: 'Jordan', AE: 'United Arab Emirates', JP: 'Japan', KR: 'South Korea', AU: 'Australia', NZ: 'New Zealand' }
const TYPOS = { complaince: 'compliance', recieve: 'receive', recieved: 'received', occured: 'occurred', accomodation: 'accommodation', accomodations: 'accommodations', interferance: 'interference', seperate: 'separate', managment: 'management', enviroment: 'environment', envirronmental: 'environmental', goverment: 'government', trainning: 'training', sufficent: 'sufficient', procces: 'process', emergancy: 'emergency', maintainance: 'maintenance', adequete: 'adequate', responsibilty: 'responsibility', worksers: 'workers', wokers: 'workers', auditted: 'audited', publically: 'publicly', refered: 'referred', recrutiment: 'recruitment', recuritment: 'recruitment', insurace: 'insurance', ovetime: 'overtime', overtme: 'overtime', calender: 'calendar', definately: 'definitely', untill: 'until', reciept: 'receipt', occassional: 'occasional', neccessary: 'necessary', necessery: 'necessary', regulaton: 'regulation', certifcate: 'certificate', acheive: 'achieve', wich: 'which', wether: 'whether', thier: 'their', teh: 'the', surverys: 'surveys', survery: 'survey', feecback: 'feedback', whith: 'with', detaling: 'detailing', contolled: 'controlled', intetrnal: 'internal', compliants: 'complaints', comunicate: 'communicate', comunicated: 'communicated', comunication: 'communication', highrisk: 'high-risk', renumeration: 'remuneration', cretche: 'crèche', pfsc: 'PEFC', employes: 'employees', payed: 'paid', salery: 'salary', wardern: 'warden', extinguisers: 'extinguishers', extinguser: 'extinguisher' }

const firstNum = s => { const m = /-?\d[\d,]*(?:\.\d+)?/.exec(String(s || '')); return m ? num(m[0]) : null }
const secOf = wr => { const m = /^(\d{1,2}(?:\.[A-Z])*)\.[A-Z]$/.exec(wr || ''); return m ? m[1] : '' }
const secOfArea = s => (/^(\d{1,2}(?:\.[A-C])?)[.\s]/.exec(String(s || '').trim()) || [])[1] || ''
const isCar = c => /^\d+\s*-\s*CAR\b/i.test(c.title || '') || /collaborative/i.test(c.verif || '')
const around = (t, i) => t.slice(Math.max(0, i - 80), i + 160)

// ---------------------------------------------------------------- parsing
function parse(doc) {
  const R = { docType: 'audit', version: '', info: {}, att: {}, times: [], foot: [], summary: [], law: [], cards: [], sections: {}, dp: [], tables: [], recognised: false, pageCount: doc.pages.length }
  const p1 = (doc.pages[0]?.lines || []).map(l => l.text).join(' ')
  const top = doc.text.slice(0, 4000)
  R.docType = /Corrective Action/i.test(p1) || (!/Ethical\s+Trade Audit Report/i.test(p1) && /Corrective Action Plan/i.test(top)) ? 'capr' : 'audit'
  const vm = /Version\s+(\d+(?:\.\d+)*)/i.exec(p1) || /SMETA\s+(?:version\s+)?(\d\.\d+)/i.exec(top)
  R.version = vm ? vm[1] : ''
  const I = R.info
  let mode = null, section = null, title = '', hdr = null, cur = null, card = null, ftype = 'NC', sumTarget = null, lastRow = null, lastAt = {}, fieldL = null, fieldR = null, dateCount = 0

  for (const p of doc.pages) {
    // footer: "Audit company: | Audit reference: | Start Date: | End Date:" then values
    const fl = p.lines.filter(l => l.y >= FOOT_Y)
    const fi = fl.findIndex(l => /^Audit company:/.test(l.text))
    if (fi >= 0 && fl[fi + 1]) {
      const c = cells(fl[fi + 1], 8).map(x => x.text)
      if (c.length >= 4) R.foot.push({ company: c[0], ref: c[1], start: c[2], end: c[3], pg: c[4] || '', page: p.n })
    }
    if (p.n === 1) continue
    const body = p.lines.filter(l => l.y < FOOT_Y && !/^For more information visit/.test(l.text))
    if (!body.length || body[0].x > 60) continue // contents, audit content, guidance pages
    for (const l of body) {
      const it0 = l.items[0], t = l.text
      // ---- headings (x 16)
      if (it0.x < 18 && it0.h >= 11) {
        cur = null; fieldL = fieldR = null
        const sm = SEC_RE.exec(t)
        if (sm) {
          section = sm[1]
          if (!R.sections[section]) R.sections[section] = { code: sm[1], name: sm[2], page: p.n, rows: [], noFindings: false, hasSummary: false, evidence: '', evPage: null, msa: {} }
          if (it0.h >= 15) mode = 'kv'
          continue
        }
        if (it0.h < 15) continue
        if (/^Findings:/i.test(t)) { mode = 'findings'; ftype = /good/i.test(t) ? 'GE' : /observ/i.test(t) ? 'OBS' : 'NC'; card = null; continue }
        if (/^Summary of findings/i.test(t)) { mode = 'summary'; sumTarget = R.summary; lastRow = null; section = null; continue }
        if (/^Local law issues/i.test(t)) { mode = 'law'; continue }
        if (/^(Audit and site details|Audit parameters|Audit attendance|SMETA declaration)/i.test(t)) { mode = 'hdr'; lastAt = {}; R.recognised = true; continue }
        if (/^(Management systems|Attachments)$/i.test(t)) { mode = 'skip'; continue }
        if (/^Data points/i.test(t)) { mode = 'kv'; continue }
        if (/^(Site details|Worker analysis|Worker interview|Measuring workplace)/i.test(t)) section = null
        if (mode !== 'kv' || !/^[a-z]/.test(t)) mode = 'kv'
        continue
      }
      if (mode === 'skip' || !mode) continue

      // ---- header pages: label → value lookup
      if (mode === 'hdr') {
        const cs = cells(l, 10)
        if (cs[0]?.text === 'Time in and out') continue
        if (cs[0] && /^(In|Out)$/.test(cs[0].text) && cs[0].x > 150) {
          const tm = cs.filter(c => TIME_RE.test(c.text)).map(c => c.text)
          tm.forEach((v, i) => { R.times[i] = R.times[i] || { day: i + 1, page: p.n }; R.times[i][cs[0].text.toLowerCase()] = v })
          continue
        }
        const am = /^([ABC]): Present at the (opening meeting|audit|closing meeting)\?/.exec(cs[0]?.text || '')
        if (am) { R.att[am[1]] = cs.slice(1).map(c => c.text); continue }
        let hit = false, lineKey = null
        for (let i = 0; i < cs.length; i++) {
          const c = cs[i]
          if (!(c.x < 40 || (c.x > 290 && c.x < 320))) continue
          const h = HL.find(x => x[1].test(c.text))
          if (!h) continue
          hit = true
          let key = h[0]
          if (key === 'apsca') key = (lineKey || 'lead') + 'Apsca'
          if (key === 'declDate' && dateCount++ > 0) key = 'repDate'
          if (!lineKey) lineKey = key
          const vals = []
          for (let j = i + 1; j < cs.length; j++) { if ((cs[j].x > 290 && cs[j].x < 320) && HL.some(x => x[1].test(cs[j].text))) break; vals.push(cs[j]) }
          const v = vals.map(x => x.text).join(h[2] ? ' | ' : ' ')
          I[key] = I[key] && v && /additional/.test(key) ? I[key] + '; ' + v : (I[key] && !v ? I[key] : v)
          I[key + 'Page'] = p.n
          if (vals[0]) lastAt[Math.round(vals[0].x)] = key
          i += vals.length
        }
        if (!hit) for (const c of cs) {
          if (c.x < 150) continue
          const k = Object.keys(lastAt).map(Number).sort((a, b) => Math.abs(a - c.x) - Math.abs(b - c.x))[0]
          if (k != null && Math.abs(k - c.x) < 20) I[lastAt[k]] = (I[lastAt[k]] ? I[lastAt[k]] + ' ' : '') + c.text
        }
        continue
      }

      // ---- summary of findings table
      if (mode === 'summary') {
        if (/^Code area\b.*\bFinding$/.test(t)) continue
        if (/^No findings$/.test(t)) { if (sumTarget !== R.summary && section) R.sections[section].noFindings = true; continue }
        const fin = l.items.filter(i => i.x >= 450)
        const pick = (a, b) => l.items.filter(i => i.x >= a && i.x < b).map(i => i.str).join(' ').replace(/\s+/g, ' ').trim()
        if (fin.length && /^(NC|GE|OBS|CAR)\b/.test(fin[0].str.trim())) {
          const ft = fin.map(i => i.str).join(' ').trim()
          const m = /^(NC|GE|OBS|CAR)\s*(Z[A-Z]{2}[\d-]*)?/.exec(ft)
          const wr = pick(160, 380)
          lastRow = { area: pick(0, 160) || (lastRow ? lastRow.area : ''), wr, wrCode: (WR_RE.exec(wr + ' ') || [])[1] || '', law: pick(380, 450), type: m[1], id: m[2] || '', page: p.n }
          sumTarget.push(lastRow)
          continue
        }
        if (lastRow && l.items.every(i => i.x < 160)) { lastRow.area += ' ' + t; continue } // wrapped code-area text
        mode = 'kv'
      }

      // ---- local law issues
      if (mode === 'law') {
        if (/^No local law issues/i.test(t)) continue
        if (it0.x < 40 && /^§\s*\d+/.test(it0.str.trim())) R.law.push({ mark: it0.str.trim().replace(/\s+/g, ''), text: l.items.slice(1).map(i => i.str).join(' '), page: p.n })
        else if (R.law.length) R.law[R.law.length - 1].text += ' ' + t
        continue
      }

      // ---- finding cards
      if (mode === 'findings') {
        if (it0.x < 40 && it0.h >= 11 && /^Z[A-Z]{2}[\d-]*$/.test(it0.str.trim())) {
          const due = (/Due\s+(\d{4}-\d{2}-\d{2})/.exec(t) || [])[1] || ''
          card = { id: it0.str.trim(), due, type: ftype, code: '', wr: '', title: '', desc: '', cap: '', lawRef: '', evidence: '', expl: '', status: '', time: '', verif: '', area: [], generated: '', page: p.n, fresh: true }
          R.cards.push(card)
          fieldL = fieldR = null
          continue
        }
        if (!card) continue
        const gm = /^\* PDF generated at (\d{1,2}:\d{2}) \(UTC\) on (.+?)\./.exec(t)
        if (gm) { card.generated = fmt(textDates(gm[2])[0]?.d); fieldL = fieldR = null; continue }
        const L = l.items.filter(i => i.x < 435), Rt = l.items.filter(i => i.x >= 435 && !/^Due\s/.test(i.str))
        if (L.length) {
          const lt = cells({ items: L }, 10).map(c => c.text).join(' | ')
          const lab = LEFT[lt] || (/^Explanation of difference/.test(lt) ? 'expl' : null)
          if (lab) {
            if (card.fresh && lab !== 'code') { const prev = R.cards[R.cards.length - 2]; if (prev && prev.id === card.id) { R.cards.pop(); card = prev } }
            card.fresh = false
            fieldL = lab
          } else if (fieldL === 'expl' && lt === 'recommendation' && !card.expl) { /* label wrap */ } else if (fieldL) card[fieldL] = (card[fieldL] ? card[fieldL] + ' ' : '') + lt
        }
        if (Rt.length) {
          const rt = Rt.map(i => i.str).join(' ').replace(/\s+/g, ' ').trim()
          const lab = RIGHT[rt]
          if (lab === 'skip') { /* "conformance" wrap */ } else if (lab) fieldR = lab
          else if (fieldR === 'area') card.area.push(rt)
          else if (fieldR) card[fieldR] = (card[fieldR] ? card[fieldR] + ' ' : '') + rt
        }
        continue
      }

      // ---- generic data points (label x < 200, value x ≥ 200) and tables
      if (mode === 'kv') {
        if (t === 'Summary of findings' && it0.x < 40) { mode = 'summary'; sumTarget = section ? R.sections[section].rows : R.summary; if (section) R.sections[section].hasSummary = true; lastRow = null; cur = null; continue }
        if (/^Men Women Other Total$/.test(t)) { hdr = 4; continue }
        if (t === 'Total' && it0.x > 500) { hdr = 1; continue }
        const lab = l.items.filter(i => i.x < 200), val = l.items.filter(i => i.x >= 200)
        if (lab.length && !val.length && it0.h >= 11) { if (t !== title) hdr = null; title = t; cur = null; continue }
        let lt = ''
        if (lab.length) {
          lt = lab.map(i => i.str).join(' ').replace(/\s+/g, ' ').trim()
          if (!cur || l.y - cur.ly > 14 || cur.page !== p.n) { cur = { label: lt, vals: [], subs: {}, page: p.n, section, title, ly: l.y }; R.dp.push(cur) } else cur.label += ' ' + lt
          cur.ly = l.y
        }
        if (val.length && cur) {
          const vc = cells({ items: val }, 10)
          if (vc.length >= 2 && vc[0].x < 216 && vc[1].x >= 385 && vc[1].x < 400) cur.subs[vc[0].text] = vc.slice(1).map(c => c.text).join(' ')
          else cur.vals.push(vc.map(c => c.text).join(' | '))
          if (lab.length && hdr && vc.every(c => /^(-|-\s+-|\d[\d,.]*%?(\s*\(\d+(?:\.\d+)?%\))?)$/.test(c.text))) {
            const row = { title, label: lt, page: p.n, raw: vc.map(c => c.text) }
            if (hdr === 4 && vc.length === 4) { [row.men, row.women, row.other, row.total] = vc.map(c => firstNum(c.text)); row.pct = vc.map(c => { const m = /\((\d+(?:\.\d+)?)%\)/.exec(c.text); return m ? m[1] : null }) }
            else if (hdr === 1 && vc.length === 1) row.total = firstNum(vc[0].text)
            R.tables.push(row)
          }
        }
      }
    }
  }
  // section evidence + MSA grades from data points
  for (const d of R.dp) {
    const s = d.section && R.sections[d.section]
    if (!s) continue
    if (/^Systems and evidence examined/i.test(d.label)) { s.evidence = d.vals.join(' '); s.evPage = d.page; s.evFound = true }
    const mk = /^(Develop and maintain|Appoint a manager|Communicate and train|Monitor the effectiveness)/.exec(d.label)
    if (mk && d.vals[0]) s.msa[mk[1]] = d.vals[0]
  }
  // fallbacks for other layouts (e.g. SMETA 6.x Word-based reports)
  const ft = R.foot[0] || {}
  const grab = re => (re.exec(doc.text) || [])[1] || ''
  R.auditRef = ft.ref || grab(/\b(ZAA\d{6,})\b/)
  I.siteRef = I.siteRef || grab(/\b(ZS\d{6,})\b/)
  I.companyRef = I.companyRef || grab(/\b(ZC\d{6,})\b/)
  R.start = ft.start || ''
  R.end = ft.end || ''
  I.auditCompany = I.auditCompany || ft.company || ''
  return R
}

const HL = [
  ['companyRef', /^Sedex company reference$/i], ['auditCompany', /^Auditor company name$/i], ['auditDate', /^Date of audit$/i], ['conductedBy', /^Audit conducted by$/i], ['pillars', /^Audit pillars$/i, true],
  ['siteRef', /^Sedex site reference$/i], ['siteName', /^Site name$/i], ['businessName', /^Business name$/i], ['address', /^Site address$/i], ['phone', /^Site phone$/i], ['email', /^Site email$/i],
  ['auditType', /^Audit type$/i], ['announced', /^Was the audit announced\?$/i], ['saq', /^Was the Sedex SAQ available for/i], ['caprSigned', /^Who signed and agreed CAPR\?/i], ['conflict', /^Any conflicting information/i], ['furtherInfo', /^Is further information available/i],
  ['reasonOpening', /^Reason for absence at the opening/i], ['reasonAudit', /^Reason for absence during the audit/i], ['reasonClosing', /^Reason for absence at the closing/i],
  ['exceptions', /^Any exceptions to the SMETA/i], ['lead', /^Lead auditor$/i], ['additional', /^Additional auditor$/i], ['apsca', /^APSCA Number$/i], ['declDate', /^Date of declaration$/i], ['repName', /^Full name$/i], ['repTitle', /^Title$/i], ['declText', /^(SMETA declaration|Declaration)$/i],
]
const LEFT = { 'Code area': 'code', 'Workplace requirement': 'wr', 'Issue title': 'title', 'Description': 'desc', 'Corrective and preventative actions': 'cap', 'Local law reference': 'lawRef', 'Evidence': 'evidence' }
const RIGHT = { 'Status': 'status', 'Time given to resolve': 'time', 'Verification method': 'verif', 'Area of non-compliance/non-': 'area', 'conformance': 'skip' }

// data point lookup helpers
const finder = R => {
  const all = re => R.dp.filter(d => re.test(d.label))
  const one = re => all(re)[0] || null
  const val = re => { const d = one(re); return d ? (d.vals[0] || '').trim() : '' }
  const sub = (re, k) => { const d = one(re); if (!d) return null; const key = Object.keys(d.subs).find(x => k.test(x)); return key ? d.subs[key] : null }
  const tab = (tre, lre) => R.tables.find(r => tre.test(r.title) && lre.test(r.label)) || null
  return { all, one, val, sub, tab }
}

// ---------------------------------------------------------------- checks
export function check(doc, file = '') {
  const { out, add } = collector(RULES)
  const F = { file }
  const R = parse(doc)
  const I = R.info
  const D = finder(R)
  const audit = R.docType === 'audit'
  const ncRows = R.summary.filter(r => r.type !== 'GE')
  const ncSecs = new Set(ncRows.map(r => secOf(r.wrCode) || secOfArea(r.area)))

  if (!R.recognised) add('SMETA-28', { ...F, page: 1, msg: R.version ? `Version ${R.version}` : '' })

  // 01 key fields
  if (R.recognised) {
    const need = [['Sedex site reference', I.siteRef], ['Sedex company reference', I.companyRef], ['Audit reference', R.auditRef], ['Site name', I.siteName], ['Site address', I.address], ['Auditor company name', I.auditCompany], ['Date of audit', I.auditDate], ['Start / end date', R.start && R.end], ['Audit type', I.auditType], ['Announced / unannounced', I.announced], ['Audit pillars', I.pillars], ['Lead auditor', I.lead], ['Lead auditor APSCA number', I.leadApsca], ['Auditor declaration date', I.declDate], ['Site representative', I.repName], ['CAPR signed by', I.caprSigned]]
    if (audit && R.tables.length) need.push(['Total workers', workerTotal(D)])
    const miss = need.filter(x => !x[1] || /^(-|n\/?a)$/i.test(String(x[1]).trim())).map(x => x[0])
    if (miss.length) add('SMETA-01', { ...F, page: I.siteRefPage || 5, msg: 'Missing: ' + miss.join(', ') })
    if (I.additional && !I.additionalApsca) add('SMETA-01', { ...F, sev: 'warning', page: I.additionalPage, msg: `Additional auditor "${I.additional}" has no APSCA number` })
  }

  // 02 dates
  const start = ymd(R.start), end = ymd(R.end), adate = ymd(I.auditDate), decl = ymd(I.declDate), rep = ymd(I.repDate)
  if (start && end && end < start) add('SMETA-02', { ...F, page: 2, msg: `End date ${fmt(end)} before start date ${fmt(start)}` })
  if (start && end && days(start, end) > 10) add('SMETA-02', { ...F, sev: 'warning', page: 2, msg: `Audit spans ${days(start, end) + 1} days (${fmt(start)} – ${fmt(end)})` })
  if (adate && start && fmt(adate) !== fmt(start)) add('SMETA-02', { ...F, page: I.auditDatePage, msg: `Date of audit ${fmt(adate)} vs start date ${fmt(start)} in the footer` })
  for (const [lab, d, pg] of [['Auditor declaration', decl, I.declDatePage], ['Site representative declaration', rep, I.repDatePage]]) {
    if (d && start && d < start) add('SMETA-02', { ...F, page: pg, msg: `${lab} dated ${fmt(d)}, before the audit started (${fmt(start)})` })
    else if (d && end && days(end, d) > 14) add('SMETA-02', { ...F, sev: 'warning', page: pg, msg: `${lab} dated ${fmt(d)}, ${days(end, d)} days after the audit ended` })
  }
  const now = new Date()
  if (end && end > now) add('SMETA-02', { ...F, page: 2, msg: `End date ${fmt(end)} is in the future` })
  const toMin = s => { const m = /(\d{1,2}):(\d{2})/.exec(s || ''); return m ? +m[1] * 60 + +m[2] : null }
  for (const d of R.times) {
    const a = toMin(d.in), b = toMin(d.out)
    if (a != null && b != null && b <= a) add('SMETA-02', { ...F, page: d.page, ref: 'Day ' + d.day, msg: `Time out ${d.out} not after time in ${d.in}` })
    if (a != null && b != null && b - a > 14 * 60) add('SMETA-02', { ...F, sev: 'warning', page: d.page, ref: 'Day ' + d.day, msg: `${d.in}–${d.out}: over 14 hours on site` })
  }
  if (start && end && R.times.length) {
    const span = days(start, end) + 1
    if (R.times.length > span) add('SMETA-02', { ...F, page: R.times[0].page, msg: `Time in/out given for ${R.times.length} days but the audit dates span ${span} day(s)` })
    else if (R.times.length < span) add('SMETA-02', { ...F, sev: 'info', page: R.times[0].page, msg: `Audit dates span ${span} calendar days (${fmt(start)} – ${fmt(end)}) but time in/out is given for ${R.times.length} day(s); check the days were not consecutive` })
  }

  // 03 reference formats + footer consistency
  const fmtChecks = [['Audit reference', R.auditRef, /^ZAA\d{6,}$/], ['Sedex site reference', I.siteRef, /^ZS\d{6,}$/], ['Sedex company reference', I.companyRef, /^ZC\d{6,}$/]]
  for (const [lab, v, re] of fmtChecks) if (v && !re.test(v.trim())) add('SMETA-03', { ...F, page: I.siteRefPage || 2, msg: `${lab} "${v}" does not look like ${re.source.slice(1, 4).replace(/\\.*/, '')}…` })
  if (R.foot.length) {
    const f0 = R.foot[0]
    const bad = R.foot.filter(f => f.ref !== f0.ref || f.start !== f0.start || f.end !== f0.end || f.company !== f0.company)
    if (bad.length) add('SMETA-03', { ...F, page: bad[0].page, msg: `Footer on ${bad.length} page(s) differs from page ${f0.page}: ${bad[0].company} / ${bad[0].ref} / ${bad[0].start}–${bad[0].end}` })
    const pg = R.foot.filter(f => f.pg && /^\d+$/.test(f.pg) && +f.pg !== f.page)
    if (pg.length) add('SMETA-03', { ...F, sev: 'info', page: pg[0].page, msg: `Printed page number ${pg[0].pg} on PDF page ${pg[0].page}` })
    if (I.auditCompany && f0.company && I.auditCompany !== f0.company && norm(I.auditCompany) !== norm(f0.company)) add('SMETA-03', { ...F, page: I.auditCompanyPage, msg: `Auditor company name "${I.auditCompany}" vs footer "${f0.company}"` })
  }
  for (const c of R.cards) if (c.id !== 'ZAF-' && !/^ZAF\d{6,}$/.test(c.id)) add('SMETA-03', { ...F, page: c.page, ref: c.id, msg: `Finding reference "${c.id}"` })

  // 04 blank finding references
  const blankC = R.cards.filter(c => /^Z[A-Z]{2}-$/.test(c.id)), blankS = R.summary.filter(c => /^Z[A-Z]{2}-$/.test(c.id))
  if (blankC.length || blankS.length) add('SMETA-04', { ...F, page: (blankS[0] || blankC[0]).page, msg: `Finding reference shown as "ZAF-" (no number): ${blankS.length} in the summary, ${blankC.length} in the finding details`, text: R.cards.find(c => c.generated)?.generated ? 'PDF generated ' + R.cards.find(c => c.generated).generated : '' })

  // 05 summary vs details
  const cardsByType = t => R.cards.filter(c => (t === 'GE' ? c.type === 'GE' : c.type !== 'GE'))
  if (R.summary.length || R.cards.length) {
    const used = new Set()
    for (const t of ['NC', 'GE']) {
      const rows = R.summary.filter(r => (t === 'GE' ? r.type === 'GE' : r.type !== 'GE'))
      const cs = cardsByType(t)
      const hasDetails = R.docType === 'capr' || cs.length > 0 || t === 'GE'
      rows.forEach((r, i) => {
        let c = r.id && !/-$/.test(r.id) ? cs.find(x => x.id === r.id) : null
        if (!c && (!r.id || /-$/.test(r.id))) c = cs.filter(x => !used.has(x)).find(x => (WR_RE.exec(x.wr + ' ') || [])[1] === r.wrCode) || null
        if (!c) {
          const other = R.cards.find(x => r.id && x.id === r.id)
          if (other) add('SMETA-05', { ...F, page: r.page, ref: r.id, msg: `Summary type ${r.type}, details list it under ${other.type === 'GE' ? 'good examples' : 'non-compliances'}` })
          else if (hasDetails && (R.docType === 'capr' || R.cards.length)) add('SMETA-05', { ...F, page: r.page, ref: r.id || r.wrCode, msg: `${r.type} ${r.wrCode} in the summary has no finding details` })
          return
        }
        used.add(c)
        const cw = (WR_RE.exec(c.wr + ' ') || [])[1] || ''
        if (r.wrCode && cw && r.wrCode !== cw) add('SMETA-05', { ...F, page: c.page, ref: c.id, msg: `Workplace requirement ${r.wrCode} in the summary, ${cw} in the details` })
        const cs1 = secOfArea(c.code), rs = secOfArea(r.area)
        if (cs1 && rs && cs1 !== rs) add('SMETA-05', { ...F, page: c.page, ref: c.id, msg: `Code area ${rs} in the summary, ${cs1} in the details` })
        if (cw && cs1 && secOf(cw) !== cs1) add('SMETA-05', { ...F, page: c.page, ref: c.id, msg: `Workplace requirement ${cw} does not belong to code area ${cs1}` })
        if (t === 'NC') {
          const ll = c.area.some(a => /local law/i.test(a))
          if (r.law && !ll) add('SMETA-05', { ...F, page: c.page, ref: c.id, msg: `Summary marks local law ${r.law}, but the area of non-compliance is ${c.area.join(', ') || 'blank'}` })
          if (!r.law && ll) add('SMETA-05', { ...F, page: r.page, ref: c.id, msg: 'Area of non-compliance includes Local law, but the summary has no local-law marker' })
        }
      })
      for (const c of cs) if (!used.has(c) && R.summary.length) add('SMETA-05', { ...F, page: c.page, ref: c.id, msg: `${c.type} ${(WR_RE.exec(c.wr + ' ') || [])[1] || ''} in the details but not in the summary of findings` })
    }
  }

  // 06 section summaries vs overall summary (audit report)
  if (audit && Object.keys(R.sections).length) {
    const key = r => r.id && !/-$/.test(r.id) ? r.id : r.type + r.wrCode
    const overall = new Map(R.summary.map(r => [key(r), r]))
    const inSec = new Set()
    for (const s of Object.values(R.sections)) {
      if (!s.hasSummary) continue
      for (const r of s.rows) {
        inSec.add(key(r))
        const o = overall.get(key(r))
        if (!o) add('SMETA-06', { ...F, page: r.page, ref: `${s.code} ${s.name}`, msg: `${r.type} ${r.id || r.wrCode} in the section summary but not in the overall summary` })
        else if (o.type !== r.type) add('SMETA-06', { ...F, page: r.page, ref: `${s.code} ${s.name}`, msg: `${r.id}: ${r.type} here, ${o.type} in the overall summary` })
      }
    }
    for (const r of R.summary) {
      const sc = secOfArea(r.area) || secOf(r.wrCode)
      const s = R.sections[sc]
      if (s && s.hasSummary && !inSec.has(key(r))) add('SMETA-06', { ...F, page: s.page, ref: `${s.code} ${s.name}`, msg: `${r.type} ${r.id || r.wrCode} in the overall summary but ${s.noFindings ? 'the section says "No findings"' : 'not in the section summary'}` })
    }
  }

  // 07–10 per non-compliance
  for (const c of R.cards) {
    const ref = `${c.id} ${(WR_RE.exec(c.wr + ' ') || [])[1] || clip(c.code, 40)}`.trim()
    if (c.type === 'GE') {
      if ((c.desc || '').length < 15) add('SMETA-07', { ...F, sev: 'warning', page: c.page, ref, msg: 'Good example without a description', text: c.desc })
      continue
    }
    const car = isCar(c)
    const miss = []
    if (!c.title) miss.push('issue title')
    if ((c.desc || '').length < 20) miss.push('description')
    if ((c.cap || '').length < 15) miss.push('corrective action')
    if (!c.status) miss.push('status')
    if (!car && !c.time) miss.push('time given to resolve')
    if (!car && !c.verif) miss.push('verification method')
    if (!c.area.length) miss.push('area of non-compliance')
    if (miss.length) add('SMETA-07', { ...F, page: c.page, ref, msg: 'Missing: ' + miss.join(', '), text: c.desc })
    if (/^\d+\s*-\s*CAR\b/i.test(c.title) !== /collaborative/i.test(c.verif) && c.verif) add('SMETA-07', { ...F, sev: 'warning', page: c.page, ref, msg: `Issue title ${/CAR/.test(c.title) ? 'is' : 'is not'} a CAR but verification method is "${c.verif}"`, text: c.title })
    // 08 local law
    if (c.area.some(a => /local law/i.test(a)) && (c.lawRef || '').replace(/local language:.*/i, '').trim().length < 15) add('SMETA-08', { ...F, page: c.page, ref, msg: 'Area of non-compliance is Local law, but no local law reference is given' })
    // 09 repeated text
    const nd = norm(c.desc), nc = norm(c.cap), nt = norm(c.title.replace(/^\d+\s*-\s*(CAR:)?/i, ''))
    if (nc && (nc === nd || nc === nt)) add('SMETA-09', { ...F, page: c.page, ref, msg: `Corrective action is identical to the ${nc === nd ? 'description' : 'issue title'}`, text: c.cap })
    else if (nd && nd === nt) add('SMETA-09', { ...F, page: c.page, ref, msg: 'Description only repeats the issue title', text: c.desc })
    // 10 title vs description
    const tm = /\b(?:has|have) been (completed|conducted|established|implemented|developed|carried out|provided)\b/i.exec(c.title)
    if (tm && new RegExp(`\\b(?:had|has|have|was|were) not (?:been )?${tm[1]}|\\bnot ${tm[1]}\\b`, 'i').test(c.desc.replace(/Local language:.*/i, ''))) add('SMETA-10', { ...F, page: c.page, ref, msg: `Title says "${tm[0]}", description says it was not ${tm[1]}`, text: c.title + ' — ' + c.desc })
  }

  // 08 local law issues list vs summary
  const marks = new Set(R.law.map(x => x.mark))
  for (const r of R.summary) for (const m of (r.law.match(/§\s*\d+/g) || [])) if (!marks.has(m.replace(/\s+/g, ''))) add('SMETA-08', { ...F, page: r.page, ref: r.id || r.wrCode, msg: `Local law marker ${m} has no entry under Local law issues` })
  const usedMarks = new Set(R.summary.flatMap(r => (r.law.match(/§\s*\d+/g) || []).map(m => m.replace(/\s+/g, ''))))
  for (const x of R.law) if (!usedMarks.has(x.mark) && R.summary.length) add('SMETA-08', { ...F, sev: 'warning', page: x.page, ref: x.mark, msg: `Local law issue ${x.mark} is not linked to any finding in the summary`, text: x.text })

  // 11 CAPR timeline
  const gen = R.cards.map(c => ymd(c.generated)).find(Boolean)
  for (const c of R.cards.filter(x => x.type !== 'GE')) {
    const ref = c.id
    const due = ymd(c.due), td = /(\d+)\s*days?/i.exec(c.time)
    if (due && end && td) {
      const off = days(end, due) - +td[1]
      if (off < 0 || off > 14) add('SMETA-11', { ...F, page: c.page, ref, msg: `Due ${fmt(due)} = audit end ${fmt(end)} + ${days(end, due)} days; time given ${td[1]} days` })
    }
    const cl = /closed\s*\((\d{4}-\d{2}-\d{2})\)/i.exec(c.status)
    if (cl) {
      const d = ymd(cl[1])
      if (end && d < end) add('SMETA-11', { ...F, sev: 'error', page: c.page, ref, msg: `Closed ${cl[1]}, before the audit ended (${fmt(end)})` })
      if (gen && d > gen) add('SMETA-11', { ...F, sev: 'error', page: c.page, ref, msg: `Closed ${cl[1]}, after the PDF was generated (${fmt(gen)})` })
    } else if (/closed|verified/i.test(c.status) && !/\d{4}-\d{2}-\d{2}/.test(c.status)) add('SMETA-11', { ...F, page: c.page, ref, msg: `Status "${c.status}" without a closure date` })
    if (/open/i.test(c.status) && due && gen && due < gen) add('SMETA-11', { ...F, sev: 'info', page: c.page, ref, msg: `Still open on ${fmt(gen)}, due ${fmt(due)}` })
  }

  // 12 worker numbers
  const tot = workerTotal(D)
  const wTitles = /^(Worker totals|Workers by type|Migrant workers|Workers by age|Workers by remuneration type|Workers by payment cycle|People in managerial)/i
  for (const r of R.tables) {
    if (r.men == null && r.women == null) continue
    const parts = [r.men, r.women, r.other].filter(v => v != null)
    if (r.total != null && parts.length >= 2 && parts.reduce((a, b) => a + b, 0) !== r.total && !/turnover|absenteeism|accidents|lost day|percentage|nationalities/i.test(r.title)) add(/interview/i.test(r.title) ? 'SMETA-13' : 'SMETA-12', { ...F, page: r.page, ref: r.title, msg: `${r.label}: ${parts.join(' + ')} = ${parts.reduce((a, b) => a + b, 0)}, total ${r.total}` })
    if (wTitles.test(r.title) && tot) {
      const vals = [r.men, r.women, r.other, r.total]
      r.pct?.forEach((p, i) => {
        if (p == null || vals[i] == null) return
        const exp = vals[i] / tot * 100, tol = /\./.test(p) ? 0.06 : 0.51
        if (Math.abs(exp - +p) > tol) add('SMETA-12', { ...F, page: r.page, ref: r.title, msg: `${r.label}: ${vals[i]} shown as ${p} %, ${vals[i]}/${tot} = ${exp.toFixed(1)} %` })
      })
      if (r.total != null && r.total > tot) add('SMETA-12', { ...F, page: r.page, ref: r.title, msg: `${r.label}: ${r.total} exceeds total workers ${tot}` })
    }
  }
  if (tot) {
    const sumT = re => { const rows = R.tables.filter(r => re.test(r.title) && r.total != null); return rows.length ? { s: rows.reduce((a, r) => a + r.total, 0), n: rows.length, page: rows[0].page } : null }
    for (const [lab, re] of [['Workers by type', /^Workers by type/i], ['Workers by remuneration type', /^Workers by remuneration/i], ['Workers by payment cycle', /^Workers by payment cycle/i]]) {
      const x = sumT(re)
      if (x && x.n >= 2 && x.s !== tot) add('SMETA-12', { ...F, page: x.page, ref: lab, msg: `${lab} add up to ${x.s}, total workers ${tot}` })
    }
    const ages = sumT(/^Workers by age/i)
    if (ages && ages.s > tot) add('SMETA-12', { ...F, page: ages.page, ref: 'Workers by age', msg: `Age bands add up to ${ages.s}, more than ${tot} workers` })
    const mig = D.tab(/^Migrant workers$/i, /^Total migrant/i), dom = D.tab(/^Migrant workers$/i, /^Domestic/i), intl = D.tab(/^Migrant workers$/i, /^International/i)
    if (mig && dom && intl && dom.total + intl.total !== mig.total) add('SMETA-12', { ...F, page: mig.page, ref: 'Migrant workers', msg: `Domestic ${dom.total} + international ${intl.total} ≠ total migrant ${mig.total}` })
    const pctDp = (re, n, lab) => {
      const d = D.one(re); const v = d ? num((d.vals[0] || '').replace('%', '')) : null
      if (v == null || n == null) return
      const exp = n / tot * 100
      if (Math.abs(exp - v) > 1.5) add('SMETA-12', { ...F, page: d.page, ref: lab, msg: `Data point says ${v} %, worker analysis gives ${n}/${tot} = ${exp.toFixed(1)} %` })
    }
    const age = ['^18 - 24', '^15 - 17', '^Under 15'].map(s => D.tab(/^Workers by age/i, new RegExp(s, 'i'))?.total)
    if (age.every(v => v != null)) pctDp(/^Percentage of workers that are age 24 or younger/i, age.reduce((a, b) => a + b, 0), 'Workers aged 24 or younger')
    if (mig) pctDp(/^Percentage of workers that are migrant/i, mig.total, 'Migrant workers')
    const perm = D.tab(/^Workers by type/i, /^Permanent/i), temp = D.tab(/^Workers by type/i, /^Temporary/i), appr = D.tab(/^Workers by type/i, /^Apprentices/i)
    if (perm && temp) pctDp(/^Percentage of workers that are permanently or temporarily employed/i, perm.total + temp.total, 'Permanent or temporary')
    if (appr) pctDp(/^Percentage of workers that are apprentices/i, appr.total, 'Apprentices')
    const yw = D.tab(/^Workers by age/i, /^15 - 17/i)
    const ywText = Object.values(R.sections).map(s => s.evidence).join(' ')
    if (yw && yw.total > 0 && /no (?:young|juvenile) workers/i.test(ywText)) add('SMETA-12', { ...F, page: yw.page, ref: 'Workers by age', msg: `${yw.total} worker(s) aged 15–17, but the evidence says there are no young workers` })
  }
  const nat = R.tables.filter(r => /nationalities/i.test(r.title) && r.total != null)
  if (nat.length >= 2) { const s = nat.reduce((a, r) => a + r.total, 0); if (s > 102) add('SMETA-12', { ...F, page: nat[0].page, ref: 'Nationalities', msg: `Nationality shares add up to ${s} %` }) }

  // 13 interviews
  const itot = D.tab(/interviewed by type/i, /^Total number of workers interviewed/i)?.total ?? firstNum(D.val(/^Total number of workers interviewed/i))
  if (itot != null) {
    const byType = R.tables.filter(r => /interviewed by type/i.test(r.title) && !/^Total/i.test(r.label) && r.total != null)
    const s = byType.reduce((a, r) => a + r.total, 0)
    if (byType.length >= 2 && s !== itot) add('SMETA-13', { ...F, page: byType[0].page, ref: 'Workers interviewed by type', msg: `Types add up to ${s}, total interviewed ${itot}` })
    const g = D.tab(/interviewed by group/i, /in groups/i), ind = D.tab(/interviewed by group/i, /individually/i)
    if (g && ind && g.total + ind.total !== itot) add('SMETA-13', { ...F, page: g.page, ref: 'Workers interviewed by group/individual', msg: `Groups ${g.total} + individual ${ind.total} = ${g.total + ind.total}, total interviewed ${itot}` })
    const gs = D.one(/^Number and size of group interviews/i)
    const gm = gs && /(\d+)\s*groups?\s*of\s*(\d+)(?!\s*[-–]|\s*to\s)/i.exec(gs.vals.join(' '))
    if (gm && g && +gm[1] * +gm[2] !== g.total) add('SMETA-13', { ...F, page: gs.page, ref: 'Group interviews', msg: `"${gm[0]}" = ${+gm[1] * +gm[2]}, workers interviewed in groups ${g.total}` })
    if (tot && itot > tot) add('SMETA-13', { ...F, page: byType[0]?.page, msg: `${itot} workers interviewed, more than the ${tot} workers on site` })
    const mi = D.tab(/^Migrant workers interviewed/i, /^Total/i), mt = D.tab(/^Migrant workers$/i, /^Total migrant/i)
    if (mi && mt && mi.total > mt.total) add('SMETA-13', { ...F, page: mi.page, ref: 'Migrant workers interviewed', msg: `${mi.total} migrant workers interviewed, but only ${mt.total} on site` })
    const repNat = D.val(/^Was the interview sample representative of all types of nationality/i)
    if (mi && mt && mt.total > 0 && mi.total === 0 && /^yes/i.test(repNat)) add('SMETA-13', { ...F, sev: 'warning', page: mi.page, ref: 'Migrant workers interviewed', msg: `${mt.total} migrant workers on site, none interviewed, yet the sample is called representative of all nationalities` })
    const wt = D.tab(/^Worker totals/i, /^Number of workers/i)
    const iw = (g?.women || 0) + (ind?.women || 0)
    if (wt && wt.total && g && ind && itot && /^yes/i.test(D.val(/^Was the interview sample representative of the gender/i))) {
      const a = wt.women / wt.total * 100, b = iw / itot * 100
      if (Math.abs(a - b) > 20) add('SMETA-13', { ...F, sev: 'warning', page: g.page, ref: 'Gender of interviewees', msg: `Women are ${a.toFixed(0)} % of workers but ${b.toFixed(0)} % of interviewees, yet the sample is called gender-representative` })
    }
    if (tot && tot > 25 && itot < Math.sqrt(tot) - 0.5) add('SMETA-13', { ...F, sev: 'info', page: byType[0]?.page, ref: 'Sample size', msg: `${itot} workers interviewed out of ${tot} (below √${tot} ≈ ${Math.round(Math.sqrt(tot))}); check against the SMETA sampling table` })
  }
  const rc = firstNum(D.val(/^Number of workers' records checked/i))
  if (rc != null && tot && rc > tot) add('SMETA-13', { ...F, page: D.one(/^Number of workers' records checked/i).page, msg: `${rc} worker records checked, more than ${tot} workers` })

  // 14 / 15 wages, hours, age
  const H = hours(D)
  const sec6 = R.sections['6']
  if (audit && R.recognised) {
    const noNc = s => !ncSecs.has(s)
    if (H.maxWeek != null && H.maxWeek > 60 && noNc('6')) add('SMETA-14', { ...F, page: H.maxWeekPage, ref: '6 Working hours', msg: `Maximum ${H.maxWeek} hours in a week, but no NC under section 6` })
    if (H.maxDays != null && H.maxDays > 6 && noNc('6')) add('SMETA-14', { ...F, page: H.maxDaysPage, ref: '6 Working hours', msg: `${H.maxDays} days worked without a day off, but no NC under section 6` })
    for (const per of ['hour', 'day', 'week', 'month']) {
      const lg = num(D.sub(/^Minimum legal wage$/i, new RegExp('per ' + per, 'i'))), ac = num(D.sub(/^Actual minimum wage$/i, new RegExp('per ' + per, 'i')))
      if (lg != null && ac != null && ac < lg && noNc('5')) add('SMETA-14', { ...F, page: D.one(/^Actual minimum wage$/i).page, ref: '5 Legal wages', msg: `Actual minimum wage per ${per} ${ac} below legal minimum ${lg}, but no NC under section 5` })
    }
    const low = D.one(/^For the lowest paid workers, are wages/i)
    if (low && /below/i.test(low.vals[0] || '') && noNc('5')) add('SMETA-14', { ...F, page: low.page, ref: '5 Legal wages', msg: `Lowest paid workers: "${low.vals[0]}", but no NC under section 5` })
    const um = firstNum(D.val(/^Enter the number of workers under local legal minimum age/i)), u15 = firstNum(D.val(/^Enter the number of workers under 15/i))
    const yg = firstNum(D.val(/^Enter the age of the youngest worker/i)), la = firstNum(D.val(/^Enter the legal age of employment/i))
    const cp = D.one(/^Enter the age of the youngest worker/i)?.page
    if (((um || 0) > 0 || (u15 || 0) > 0 || (yg != null && la != null && yg < la)) && noNc('4')) add('SMETA-14', { ...F, page: cp, ref: '4 Child labour', msg: `Under-age data (under legal age ${um ?? '-'}, under 15 ${u15 ?? '-'}, youngest ${yg ?? '-'} vs legal age ${la ?? '-'}), but no NC under section 4` })
    if (sec6 && noNc('6')) for (const m of sec6.evidence.matchAll(/(\d{2,3}(?:\.\d+)?)\s*(?:hours|hrs|h)\s*(?:per|a|in a|\/)\s*week/gi)) if (+m[1] > 60) { add('SMETA-14', { ...F, page: sec6.evPage, ref: '6 Working hours', msg: `Evidence mentions ${m[1]} hours per week, but no NC under section 6`, text: around(sec6.evidence, m.index) }); break }
    // 15
    if (H.maxWeek != null && H.reg != null && H.otWeek === 0 && H.maxWeek > H.reg + 0.5) add('SMETA-15', { ...F, page: H.otPage || H.maxWeekPage, ref: '6 Working hours', msg: `Maximum week ${H.maxWeek} h vs regular ${H.reg} h, but actual overtime is recorded as 0 h per week` })
    if (H.avg != null && H.reg != null && H.avg < H.reg - 0.5) add('SMETA-15', { ...F, page: H.avgPage, ref: '6 Working hours', msg: `Average hours including overtime (${H.avg}) below regular hours (${H.reg})` })
    if (H.avg != null && H.maxWeek != null && H.avg > H.maxWeek + 0.5) add('SMETA-15', { ...F, page: H.avgPage, ref: '6 Working hours', msg: `Average hours (${H.avg}) above the maximum week in the sample (${H.maxWeek})` })
    if (sec6 && H.maxWeek != null) for (const m of sec6.evidence.matchAll(/maximum (?:of )?(\d{2,3}(?:\.\d+)?)\s*(?:hours|hrs|h)\s*(?:per|a|in a|\/)\s*week/gi)) if (Math.abs(+m[1] - H.maxWeek) > 0.5) add('SMETA-15', { ...F, page: sec6.evPage, ref: '6 Working hours', msg: `Evidence says maximum ${m[1]} h/week, data point says ${H.maxWeek}`, text: around(sec6.evidence, m.index) })
    if (H.otWeek === 0 && H.otMonth === 0) {
      const ac = D.one(/^Additional comments$/i)
      const tx = ac ? ac.vals.join(' ') : ''
      const m = /\b(?:they|workers?)\b[^.]{0,40}\b(?:sometimes |occasionally )?(?:have|work|worked|do|did) (?:some |sometimes )?overtime\b/i.exec(tx)
      if (m) add('SMETA-15', { ...F, page: ac.page, ref: 'Worker interviews', msg: 'Workers describe overtime, but actual overtime hours are recorded as 0', text: around(tx, m.index) })
    }
  }

  // 16 data point answer vs comment / same question elsewhere
  const SKIP_DUP = /^(Develop and maintain|Appoint a manager|Communicate and train|Monitor the effectiveness|Explanation for management|Systems and evidence|Gender disaggregated|Number of workers|Last full|Previous full|Max hours|Min per)/i
  const byQ = new Map()
  for (const d of R.dp) {
    const a = (d.vals[0] || '').trim()
    if (!/^(yes|no|not applicable|n\/a)\b/i.test(a) || d.label.length < 25 || SKIP_DUP.test(d.label)) continue
    const k = norm(d.label)
    if (!byQ.has(k)) byQ.set(k, [])
    byQ.get(k).push({ d, a })
    const comment = d.vals.slice(1).join(' ')
    if (/^no$/i.test(a) && /^\s*all\b[^.]{0,80}\b(?:were|was|are)\s+(?:included|covered|interviewed|reviewed|sampled)\b/i.test(comment)) add('SMETA-16', { ...F, page: d.page, ref: clip(d.label, 70), msg: `Answer "No", comment says "${clip(comment, 80)}"` })
    if (/^yes$/i.test(a) && comment && negHits(comment)) add('SMETA-16', { ...F, sev: 'info', page: d.page, ref: clip(d.label, 70), msg: `Answer "Yes", comment mentions "${negHits(comment)}"`, text: comment })
  }
  for (const [, g] of byQ) {
    const ans = new Set(g.map(x => norm(x.a.replace(/^n\/a$/i, 'not applicable').split(/\s/).slice(0, 2).join(' '))))
    if (g.length > 1 && ans.size > 1) add('SMETA-16', { ...F, page: g[0].d.page, ref: clip(g[0].d.label, 70), msg: g.map(x => `"${x.a}" (p${x.d.page}${x.d.section ? ', section ' + x.d.section : ''})`).join(' vs ') })
  }

  // 17 No findings but evidence describes a gap
  for (const s of Object.values(R.sections)) {
    if (!s.noFindings || ncSecs.has(s.code)) continue
    const h = negHits(s.evidence)
    if (h) add('SMETA-17', { ...F, page: s.evPage || s.page, ref: `${s.code} ${s.name}`, msg: `"No findings", but the evidence says "${h}"`, text: around(s.evidence, s.evidence.toLowerCase().indexOf(h.toLowerCase())) })
  }

  // 18 environment
  const yv = re => { const d = D.one(re); if (!d) return null; const v = d.vals.join(' | ').split('|').map(x => num(x.trim())); return { v, page: d.page } }
  const eNr = yv(/^Total electricity consumption from non-?\s*renewable/i), eR = yv(/^Total electricity consumption from renewable/i)
  if (eNr && eR) eNr.v.forEach((v, i) => { if (v && v === eR.v[i]) add('SMETA-18', { ...F, page: eNr.page, ref: 'Usage/discharge analysis', msg: `Electricity from non-renewable and renewable sources both ${v.toLocaleString('en')} kWh (${i ? 'previous' : 'last'} year): one row was probably copied` }) })
  const wt = yv(/^Total waste produced/i), wh = yv(/^Total hazardous waste produced/i), routes = [/^Waste to recycling/i, /^Waste to landfill/i, /^Waste to other/i].map(yv)
  if (wt) wt.v.forEach((tw, i) => {
    if (tw == null) return
    if (wh && wh.v[i] != null && wh.v[i] > tw) add('SMETA-18', { ...F, page: wh.page, ref: 'Usage/discharge analysis', msg: `Hazardous waste ${wh.v[i]} mt exceeds total waste ${tw} mt` })
    const rs = routes.map(r => r && r.v[i]).filter(v => v != null)
    if (rs.length >= 2) { const s = rs.reduce((a, b) => a + b, 0); if (s > tw * 1.005 + 1) add('SMETA-18', { ...F, page: wt.page, ref: 'Usage/discharge analysis', msg: `${i ? 'Previous' : 'Last'} year: recycling + landfill + other = ${s.toLocaleString('en')} mt, more than total waste ${tw.toLocaleString('en')} mt` }) }
  })
  const wu = yv(/^Water volume used/i), wr = yv(/^Water volume recycled/i)
  if (wu && wr) wu.v.forEach((u, i) => { if (u != null && wr.v[i] != null && wr.v[i] > u) add('SMETA-18', { ...F, page: wr.page, ref: 'Usage/discharge analysis', msg: `Water recycled ${wr.v[i]} m³ exceeds water used ${u} m³` }) })

  // 19 attendance
  const reasons = [I.reasonOpening, I.reasonAudit, I.reasonClosing]
  ;['A', 'B', 'C'].forEach((k, i) => { const row = R.att[k]; if (row && row.some(v => /^no$/i.test(v)) && !(reasons[i] || '').trim()) add('SMETA-19', { ...F, page: I.reasonOpeningPage || I.auditTypePage, ref: ['Opening meeting', 'Audit', 'Closing meeting'][i], msg: 'Someone was absent but no reason is given' }) })
  const unionPresent = Object.values(R.att).some(r => /^yes$/i.test(r[2] || '')), wrPresent = Object.values(R.att).some(r => /^yes$/i.test(r[1] || ''))
  const regUnion = D.val(/^Are there any registered trade unions in/i)
  if (unionPresent && /^no$/i.test(regUnion)) add('SMETA-19', { ...F, page: D.one(/^Are there any registered trade unions in/i).page, msg: 'A union representative attended the audit, but the report says there is no registered trade union' })
  const freeEl = D.val(/^Are the worker representatives freely elected/i)
  if (!wrPresent && R.att.A && /^yes$/i.test(freeEl) && /no worker representative/i.test(reasons.join(' '))) add('SMETA-19', { ...F, page: I.reasonOpeningPage, msg: 'Absence reason says there are no worker representatives, but data points say representatives are freely elected' })

  // 20 CAPR signer
  if (I.caprSigned && I.repName) {
    const nm = norm(I.caprSigned.split('/')[0])
    if (nm && norm(I.repName) && nm !== norm(I.repName)) add('SMETA-20', { ...F, page: I.caprSignedPage, msg: `CAPR signed by "${I.caprSigned}", site representative "${I.repName}"` })
  }

  // 26 pillars vs sections
  const pil = I.pillars || ''
  const four = /4-Pillar|Business ethics/i.test(pil), two = pil && !four
  if (audit && Object.keys(R.sections).length > 5) {
    if (four && (!R.sections['10.B'] || !R.sections['10.C'])) add('SMETA-26', { ...F, page: I.pillarsPage, msg: `4-pillar audit, but section ${!R.sections['10.B'] ? '10.B' : '10.C'} is missing` })
    if (two && (R.sections['10.B'] || R.sections['10.C'])) add('SMETA-26', { ...F, page: I.pillarsPage, msg: '2-pillar audit, but the report has 10.B / 10.C sections' })
  }
  if (two && R.summary.some(r => /^10\.[BC]/.test(r.wrCode))) add('SMETA-26', { ...F, page: R.summary[0].page, msg: '2-pillar audit with findings under 10.B / 10.C' })

  // 24 MSA robust with NCs
  for (const s of Object.values(R.sections)) {
    const g = Object.values(s.msa)
    if (g.length === 4 && g.every(v => /^robust/i.test(v)) && R.summary.some(r => r.type === 'NC' && (secOfArea(r.area) || secOf(r.wrCode)) === s.code && !isCar(R.cards.find(c => c.id === r.id) || {}))) add('SMETA-24', { ...F, page: s.page, ref: `${s.code} ${s.name}`, msg: 'All four management-system elements graded "Robust", yet the section has a non-compliance' })
  }

  // 21–23, 27 free text
  const texts = []
  for (const d of R.dp) if (d.vals.length && !/^[\d,.\s|%()-]+$/.test(d.vals.join(''))) texts.push({ t: d.vals.join(' '), page: d.page, ref: clip(d.label, 60) })
  for (const c of R.cards) for (const k of ['desc', 'cap', 'expl', 'lawRef']) if (c[k]) texts.push({ t: c[k], page: c.page, ref: c.id + ' ' + k })
  for (const k of ['reasonOpening', 'reasonAudit', 'reasonClosing', 'exceptions']) if (I[k]) texts.push({ t: I[k], page: I[k + 'Page'], ref: k })
  const seenT = new Set(), seenP = new Set(), seenD = new Set()
  for (const x of texts) {
    const t = x.t.replace(/Local language:.*$/i, '')
    for (const m of t.matchAll(/(?<!\p{L})\p{L}+(?!\p{L})/gu)) {
      const w = m[0].toLowerCase()
      if (TYPOS[w] && !seenT.has(w)) { seenT.add(w); add('SMETA-21', { ...F, page: x.page, ref: x.ref, msg: `"${m[0]}" → "${TYPOS[w]}"`, text: around(t, m.index) }) }
    }
    for (const m of t.matchAll(/(?<!\p{L})([a-z]{2,})\s+\1(?!\p{L})/giu)) {
      const w = m[1].toLowerCase()
      if (/^(that|had|is|bye|no)$/.test(w) || seenD.has(w)) continue
      seenD.add(w); add('SMETA-21', { ...F, page: x.page, ref: x.ref, msg: `Doubled word "${m[0]}"`, text: around(t, m.index) })
    }
    const ph = PLACEHOLDER.exec(t)
    if (ph && !seenP.has(ph[0].toLowerCase())) { seenP.add(ph[0].toLowerCase()); add('SMETA-22', { ...F, page: x.page, ref: x.ref, msg: `"${ph[0]}"`, text: around(t, ph.index) }) }
    const sents = t.split(/(?<=[.;])\s+/).map(s => s.trim()).filter(s => s.length > 40)
    for (let i = 1; i < sents.length; i++) if (norm(sents[i]) === norm(sents[i - 1])) { add('SMETA-23', { ...F, page: x.page, ref: x.ref, text: sents[i] }); break }
    for (const m of t.matchAll(/\b(\d+)\s+out of\s+(\d+)\s*(?:\(\s*(\d+(?:\.\d+)?)\s*%\s*\))?/gi)) {
      const a = +m[1], b = +m[2]
      if (a > b) add('SMETA-27', { ...F, page: x.page, ref: x.ref, msg: `"${m[0]}": ${a} > ${b}`, text: around(t, m.index) })
      else if (m[3] && b > 0 && Math.abs(a / b * 100 - +m[3]) > 1.01) add('SMETA-27', { ...F, page: x.page, ref: x.ref, msg: `"${m[0]}": ${a}/${b} = ${(a / b * 100).toFixed(1)} %`, text: around(t, m.index) })
    }
  }
  // "Other (provide details)" chosen without details
  for (const d of R.dp) {
    const i = d.vals.findIndex(v => /^Other \(provide details\)$/i.test(v.trim()))
    if (i >= 0 && d.vals.length === 1) add('SMETA-22', { ...F, page: d.page, ref: clip(d.label, 70), msg: '"Other (provide details)" selected, no details given' })
  }
  if (audit) for (const s of Object.values(R.sections)) if (s.hasSummary && s.evFound && s.evidence.trim().length < 30) add('SMETA-22', { ...F, page: s.evPage || s.page, ref: `${s.code} ${s.name}`, msg: '"Systems and evidence examined" is blank or too short', text: s.evidence })

  const stats = { findings: R.cards.length, ncs: R.cards.filter(c => c.type !== 'GE').length, sections: Object.keys(R.sections).length, dataPoints: R.dp.length }
  return { kind: 'smeta', file, meta: meta(R, file), findings: out, stats, R }
}

function workerTotal(D) { return D.tab(/^Worker totals/i, /^Number of workers/i)?.total ?? null }

function hours(D) {
  const g = re => { const d = D.one(re); return d ? { v: num((d.vals[0] || '').replace(/[^\d.,-]/g, '')), page: d.page } : { v: null } }
  const mw = g(/^In the sample, what was the maximum number of hours worked in a single week/i), md = g(/^Maximum number of days worked without a day off/i)
  const rg = g(/^Excluding overtime, what are the regular working hours per week/i), av = g(/^Including overtime, what is the average number of working hours per week/i)
  const ot = D.one(/^Actual overtime hours$/i)
  const sub = k => { if (!ot) return null; const key = Object.keys(ot.subs).find(x => k.test(x)); return key ? num(ot.subs[key]) : null }
  return { maxWeek: mw.v, maxWeekPage: mw.page, maxDays: md.v, maxDaysPage: md.page, reg: rg.v, avg: av.v, avgPage: av.page, otWeek: sub(/per week/i), otMonth: sub(/per month/i), otDay: sub(/per day/i), otPage: ot?.page }
}

// NEG with extra exclusions for statements that confirm the absence of a problem
function negHits(s) {
  const t = String(s || '').replace(/\bno evidence of (?:any )?(?:\w+ ){0,2}(?:harassment|abuse|discrimination|forced|bonded|child|bribery|corruption|violence|retaliation|coercion|falsif\w*|young)\b/gi, ' ').replace(/\b(?:there (?:was|were|is|are) )?no (?:reported )?(?:complaints?|grievances?|accidents?|incidents?|fines?)\b/gi, ' ')
  const m = t.match(NEG)
  return m ? m[0] : null
}

function country(R) {
  const a = R.info.address || ''
  const m = /,\s*([A-Z]{2})\s*$/.exec(a.trim())
  if (m) return ISO2[m[1]] || m[1]
  return ''
}

function meta(R, file) {
  const I = R.info
  const ncs = R.cards.filter(c => c.type !== 'GE')
  const nNc = R.summary.filter(r => r.type !== 'GE').length, nGe = R.summary.filter(r => r.type === 'GE').length
  const nCar = ncs.filter(isCar).length
  return {
    type: `SMETA${R.version ? ' ' + R.version : ''} – ${R.docType === 'capr' ? 'Corrective Action Plan Report (CAPR)' : 'audit report'}${R.recognised ? '' : ' (layout not recognised)'}`,
    title: I.siteName || I.businessName || file,
    fields: [['Audit ref.', R.auditRef], ['Sedex site ref.', I.siteRef], ['Audit company', I.auditCompany], ['Audit dates', [R.start, R.end].filter(Boolean).join(' – ')], ['Audit type', [I.auditType, I.announced].filter(Boolean).join(', ')], ['Pillars', pillars(I.pillars)], ['Lead auditor', I.lead], ['Findings', R.summary.length ? `${nNc} NC (${nCar} CAR) · ${nGe} good example(s)` : ''], ['Country', country(R)]].filter(f => f[1]),
    ref: R.auditRef,
  }
}
const pillars = s => !s ? '' : /4-Pillar|Business ethics/i.test(s) ? '4-Pillar' : '2-Pillar'

export function crossCheck(results) {
  const { out, add } = collector(RULES)
  const byRef = new Map()
  for (const r of results) if (r.kind === 'smeta' && r.meta.ref) { if (!byRef.has(r.meta.ref)) byRef.set(r.meta.ref, []); byRef.get(r.meta.ref).push(r) }
  for (const [ref, g] of byRef) {
    const rep = g.find(r => r.R.docType === 'audit') || g[0]
    for (const o of g) {
      if (o === rep) continue
      const a = rep.R, b = o.R
      const pairs = [['Sedex site reference', a.info.siteRef, b.info.siteRef], ['Sedex company reference', a.info.companyRef, b.info.companyRef], ['Site name', a.info.siteName, b.info.siteName], ['Audit company', a.info.auditCompany, b.info.auditCompany], ['Start date', a.start, b.start], ['End date', a.end, b.end], ['Audit type', a.info.auditType, b.info.auditType], ['Announced', a.info.announced, b.info.announced], ['Lead auditor', a.info.lead, b.info.lead], ['Audit pillars', a.info.pillars, b.info.pillars]]
      for (const [k, x, y] of pairs) if (x && y && norm(x) !== norm(y)) add('SMETA-25', { file: o.file, ref, msg: `${k}: "${y}" vs "${x}" in ${rep.file}` })
      const key = r => r.id && !/-$/.test(r.id) ? r.type + ' ' + r.id : r.type + ' ' + r.wrCode
      const sa = new Set(a.summary.map(key)), sb = new Set(b.summary.map(key))
      const onlyA = [...sa].filter(x => !sb.has(x)), onlyB = [...sb].filter(x => !sa.has(x))
      if (onlyA.length || onlyB.length) add('SMETA-25', { file: o.file, ref, msg: `Findings differ: ${onlyB.length ? 'only in ' + o.file + ': ' + onlyB.join(', ') : ''}${onlyA.length && onlyB.length ? '; ' : ''}${onlyA.length ? 'only in ' + rep.file + ': ' + onlyA.join(', ') : ''}` })
    }
  }
  return out
}

export function detect(text) {
  const t = String(text || '').slice(0, 20000)
  if (/amfori|Validated Audit Report|EcoVadis|\bCDP\b.*(?:Climate Change|Water Security) \d{4}|Clarity/i.test(t.slice(0, 3000))) return false
  return /Sedex Members Ethical\s+Trade Audit|SMETA Corrective Action\s+Plan Report|\bSMETA\b[\s\S]{0,4000}\bSedex\b|\bSedex\b[\s\S]{0,4000}\bSMETA\b/i.test(t)
}

