export function extract(R, file = '') {
  const I = R.info, D = finder(R)
  const tab = (t, l) => D.tab(t, l)
  const wt = tab(/^Worker totals/i, /^Number of workers/i)
  const tv = (t, l) => { const r = tab(t, l); return r && r.total != null ? r.total : '' }
  const ncs = R.cards.filter(c => c.type !== 'GE')
  const sumNc = R.summary.filter(r => r.type !== 'GE'), sumGe = R.summary.filter(r => r.type === 'GE')
  const H = hours(D)
  const wageStr = (re) => { const d = D.one(re); if (!d) return ''; return Object.entries(d.subs).filter(([, v]) => num(v) != null).map(([k, v]) => `${v} ${k.replace(/^(Min|Actual)\s+/i, '')}`).join('; ') }
  const att = i => { const v = Object.values(R.att).map(r => r[i]).filter(Boolean); return v.length ? (v.some(x => /^yes/i.test(x)) ? 'Yes' : 'No') : '' }
  const weak = Object.values(R.sections).filter(s => Object.values(s.msa).some(v => !/^robust/i.test(v))).map(s => s.code)
  const nat = R.tables.filter(r => /nationalities/i.test(r.title)).map(r => `${r.label} ${r.raw[3] || ''}`.trim())
  const certs = [D.val(/^Does this site hold any certifications/i), ...(D.one(/^Does this site hold any certifications/i)?.vals.slice(1) || [])].filter(Boolean).join(' ')
  const gen = R.cards.map(c => c.generated).find(Boolean) || ''
  const report = {
    file,
    doc_type: R.docType === 'capr' ? 'CAPR' : 'Audit report',
    smeta_version: R.version,
    audit_ref: R.auditRef || '',
    site_ref: I.siteRef || '',
    company_ref: I.companyRef || '',
    site_name: I.siteName || '',
    business_name: I.businessName || '',
    country: country(R),
    address: I.address || '',
    site_function: D.val(/^Site function$/i),
    products: D.val(/^Product type$/i),
    audit_company: I.auditCompany || '',
    conducted_by: I.conductedBy || '',
    pillars: pillars(I.pillars),
    pillar_list: (I.pillars || '').replace(/\s*\|\s*/g, ', '),
    audit_type: I.auditType || '',
    announced: I.announced || '',
    start_date: R.start || '',
    end_date: R.end || '',
    audit_days: R.times.length || '',
    lead_auditor: I.lead || '',
    lead_apsca: I.leadApsca || '',
    other_auditors: I.additional || '',
    declaration_date: I.declDate || '',
    site_rep: [I.repName, I.repTitle].filter(Boolean).join(', '),
    capr_signed_by: I.caprSigned || '',
    exceptions: I.exceptions || '',
    worker_rep_present: att(1),
    union_rep_present: att(2),
    workers_total: wt?.total ?? '',
    workers_men: wt?.men ?? '',
    workers_women: wt?.women ?? '',
    workers_permanent: tv(/^Workers by type/i, /^Permanent/i),
    workers_temporary: tv(/^Workers by type/i, /^Temporary/i),
    workers_agency: tv(/^Workers by type/i, /^Agency/i),
    workers_migrant: tv(/^Migrant workers$/i, /^Total migrant/i),
    workers_migrant_intl: tv(/^Migrant workers$/i, /^International/i),
    workers_15_17: tv(/^Workers by age/i, /^15 - 17/i),
    nationalities: nat.join('; '),
    workers_interviewed: tv(/interviewed by type/i, /^Total number/i),
    records_checked: firstNum(D.val(/^Number of workers' records checked/i)) ?? '',
    regular_hours_week: H.reg ?? '',
    avg_hours_week: H.avg ?? '',
    max_hours_week: H.maxWeek ?? '',
    max_days_no_rest: H.maxDays ?? '',
    ot_premium: D.val(/^Normal day overtime premium/i),
    legal_min_wage: wageStr(/^Minimum legal wage$/i),
    actual_min_wage: wageStr(/^Actual minimum wage$/i),
    turnover_last_year: (tab(/turnover/i, /^Last full calendar year/i)?.raw || [])[3] || '',
    grievances_12m: firstNum(D.val(/^Number of grievances raised/i)) ?? '',
    certifications: certs,
    nc_total: R.summary.length || R.cards.length ? (sumNc.length || ncs.length) : '',
    nc_car: ncs.filter(isCar).length,
    nc_local_law: sumNc.filter(r => r.law).length,
    nc_open: ncs.filter(c => /open|progress/i.test(c.status)).length,
    nc_closed: ncs.filter(c => /closed|verified/i.test(c.status)).length,
    nc_sections: [...new Set(sumNc.map(r => r.area.replace(/\s+/g, ' ').trim()))].join('; '),
    observations: R.summary.filter(r => r.type === 'OBS').length,
    good_examples: sumGe.length || R.cards.filter(c => c.type === 'GE').length,
    good_example_areas: [...new Set(sumGe.map(r => r.wrCode))].join(', '),
    msa_weak_sections: weak.join(', '),
    pdf_generated: gen,
  }
  const sumById = new Map(R.summary.map(r => [r.id, r]))
  const rows = ncs.map(c => {
    const wr = (WR_RE.exec(c.wr + ' ') || [])[1] || ''
    const st = /^(.*?)\s*\((\d{4}-\d{2}-\d{2})\)/.exec(c.status.replace(/\*$/, ''))
    const tm = /^(\d+)\s*-\s*(?:CAR:\s*)?(.*)$/.exec(c.title)
    return {
      file, audit_ref: R.auditRef || '', site_name: I.siteName || '',
      finding_ref: c.id, type: isCar(c) ? 'CAR' : (c.type === 'OBS' ? 'Observation' : 'NC'),
      code_section: c.code, workplace_req: c.wr, issue_code: tm ? tm[1] : '', issue_title: tm ? tm[2] : c.title,
      description: c.desc, area: c.area.join(', '), local_law_ref: c.lawRef || (sumById.get(c.id)?.law ? R.law.find(x => x.mark === sumById.get(c.id).law)?.text || '' : ''),
      corrective_action: c.cap, time_given: c.time, due_date: c.due, verification: c.verif,
      status: st ? st[1] : c.status.replace(/\*$/, ''), status_date: st ? st[2] : '', explanation: c.expl, page: c.page,
    }
  })
  return { report, rows }
}
